&nbsp;&nbsp;printf(&quot;Talk&nbsp;is&nbsp;cheap.&nbsp;Show&nbsp;me&nbsp;the&nbsp;code.&quot;);\n&nbsp;&nbsp;&nbsp;&nbsp;return&nbsp;0;\n}</pre><p><br/></p>','11.png',0,445,0,0,0,0,1,'2023-05-31 18:44:34','2023-05-31 18:44:34'),(305,2,11,'c语言编程练习题：7-181 猫是液体','<p><img src=\"/upload/20230531_184559.png\" title=\"image.png\" alt=\"image.png\"/></p><pre class=\"brush:cpp;toolbar:false\">#include&nbsp;&lt;stdio.h&gt;\nint&nbsp;main(){\n&nbsp;&nbsp;&nbsp;&nbsp;int&nbsp;a,b,c;\n&nbsp;&nbsp;&nbsp;&nbsp;if&nbsp;(scanf(&quot;%d&nbsp;%d&nbsp;%d&quot;,&amp;a,&amp;b,&amp;c)!=EOF){\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;printf(&quot;%d&quot;,a*b*c);\n&nbsp;&nbsp;&nbsp;&nbsp;}\n&nbsp;&nbsp;&nbsp;&nbsp;return&nbsp;0;\n}</pre><p><br/></p>','11.png',0,428,0,0,0,0,1,'2023-05-31 18:46:34','2023-05-31 18:46:34'),(306,2,11,'c语言编程练习题：7-182 洛希极限','<p><img src=\"/upload/20230531_184743.png\" title=\"image.png\" alt=\"image.png\"/></p><pre class=\"brush:cpp;toolbar:false\">#include&nbsp;&lt;stdio.h&gt;\nint&nbsp;main(){\n&nbsp;&nbsp;&nbsp;&nbsp;double&nbsp;a,b,c;\n&nbsp;&nbsp;&nbsp;&nbsp;double&nbsp;v;\n&nbsp;&nbsp;&nbsp;&nbsp;if&nbsp;(scanf(&quot;%lf&nbsp;%lf&nbsp;%lf&quot;,&amp;a,&amp;b,&amp;c)!=EOF){\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;if&nbsp;(b==0.0){\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;v&nbsp;=&nbsp;2.455*a;&nbsp;&nbsp;&nbsp;&nbsp;\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;}else{v&nbsp;=&nbsp;1.26*a;}\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;if&nbsp;(v&gt;c){printf(&quot;%.2f&nbsp;T_T&quot;,v);}\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;if&nbsp;(v&lt;c){printf(&quot;%.2f&nbsp;^_^&quot;,v);}\n&nbsp;&nbsp;&nbsp;&nbsp;}\n&nbsp;&nbsp;&nbsp;&nbsp;return&nbsp;0;\n}</pre><p><br/></p>','11.png',0,428,0,0,0,0,1,'2023-05-31 18:48:49','2023-05-31 18:48:49'),(307,2,11,'c语言编程练习题：7-183 调和平均','<p><img src=\"/upload/20230604_184152.png\" title=\"image.png\" alt=\"image.png\"/></p><pre class=\"brush:cpp;toolbar:false\">#include&nbsp;&lt;stdio.h&gt;\nint&nbsp;main(){\n&nbsp;&nbsp;&nbsp;&nbsp;int&nbsp;n;\n&nbsp;&nbsp;&nbsp;&nbsp;double&nbsp;v;\n&nbsp;&nbsp;&nbsp;&nbsp;double&nbsp;sum=0.0,avg=0.0;\n&nbsp;&nbsp;&nbsp;&nbsp;if&nbsp;(scanf(&quot;%d&quot;,&amp;n)!=EOF){\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;for&nbsp;(int&nbsp;i=0;i&lt;n;i++){\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;if&nbsp;(scanf(&quot;%lf&quot;,&amp;v)!=EOF){\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;sum+=1.0/v;\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;}\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;}\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;avg&nbsp;=&nbsp;1.0*n/sum;\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;printf(&quot;%.2lf&quot;,avg);\n&nbsp;&nbsp;&nbsp;&nbsp;}\n&nbsp;&nbsp;&nbsp;&nbsp;return&nbsp;0;\n}</pre><p><br/></p>','11.png',0,429,0,0,0,0,1,'2023-06-04 18:42:16','2023-06-04 18:42:16'),(308,2,11,'c语言编程练习题：7-184 胎压监测','<p><img src=\"/upload/20230604_184418.png\" title=\"image.png\" alt=\"image.png\"/></p><pre class=\"brush:cpp;toolbar:false\">#include&nbsp;&lt;stdio.h&gt;\nint&nbsp;main(){\n&nbsp;&nbsp;&nbsp;&nbsp;int&nbsp;a,b,c,d,high,s;\n&nbsp;&nbsp;&nbsp;&nbsp;if&nbsp;(scanf(&quot;%d&nbsp;%d&nbsp;%d&nbsp;%d&nbsp;%d&nbsp;%d&quot;,&amp;a,&amp;b,&amp;c,&amp;d,&amp;high,&amp;s)!=EOF){\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;int&nbsp;arr[4]={a,b,c,d};\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;int&nbsp;r&nbsp;=&nbsp;0;\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;int&nbsp;count=0;\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;int&nbsp;max_value&nbsp;=&nbsp;0;\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;for&nbsp;(int&nbsp;j=0;j&lt;4;j++){if&nbsp;(arr[j]&gt;max_value){max_value=arr[j];}}\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;for&nbsp;(int&nbsp;i=0;i&lt;4;i++){\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;if&nbsp;(arr[i]&lt;high&nbsp;||&nbsp;max_value-arr[i]&gt;s){\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;r=i;\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;count++;\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;}\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;}\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;if&nbsp;(count==0){printf(&quot;Normal&quot;);}\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;if&nbsp;(count==1){printf(&quot;Warning:&nbsp;please&nbsp;check&nbsp;#%d!&quot;,r+1);}\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;if&nbsp;(count&gt;=2){printf(&quot;Warning:&nbsp;please&nbsp;check&nbsp;all&nbsp;the&nbsp;tires!&quot;);}\n\n&nbsp;&nbsp;&nbsp;&nbsp;}\n&nbsp;&nbsp;&nbsp;&nbsp;return&nbsp;0;\n}</pre><p><br/></p>','11.png',0,437,0,0,0,0,1,'2023-06-04 18:45:19','2023-06-04 18:45:19'),(309,2,11,'c语言编程练习题：7-185 吃火锅','<p><img src=\"/upload/20230604_184614.png\" title=\"image.png\" alt=\"image.png\"/></p><pre class=\"brush:cpp;toolbar:false\">#include&lt;stdio.h&gt;\n#include&lt;string.h&gt;\nint&nbsp;main()\n{\n&nbsp;&nbsp;&nbsp;&nbsp;int&nbsp;num1=0,num2=0,first=0;\n&nbsp;&nbsp;&nbsp;&nbsp;char&nbsp;ch1[]=&quot;chi1&nbsp;huo3&nbsp;guo1&quot;;\n&nbsp;&nbsp;&nbsp;&nbsp;char&nbsp;arr[81];\n&nbsp;&nbsp;&nbsp;&nbsp;char&nbsp;ch;\n&nbsp;&nbsp;&nbsp;&nbsp;while&nbsp;(1){\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;//&nbsp;fgets(arr,81,stdin);\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;//&nbsp;int&nbsp;count&nbsp;=&nbsp;0;\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;//&nbsp;while&nbsp;(scanf(&quot;%c&quot;,&amp;ch)!=EOF&nbsp;&amp;&amp;&nbsp;ch!=&#39;\\n&#39;){\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;//&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;arr[count]&nbsp;=&nbsp;ch;\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;//&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;count++;\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;//&nbsp;}\n