/p><p>可考虑基于这个思路做一个策略</p>','2023-06-07 15:40:20','2023-12-31 00:00:00',NULL,0,NULL,NULL,4),(1573,1,'阅读《bit做市代码》','',NULL,NULL,'2023-06-12 09:42:39',18849,NULL,'2023-06-12 09:42:35',2),(1575,1,'拆分函数，优化函数','',NULL,NULL,'2023-06-13 16:42:07',24780,NULL,'2023-06-13 16:42:02',2),(1577,1,'生日提醒','',NULL,NULL,'2023-06-25 09:38:11',0,NULL,NULL,2),(1578,1,'《如何是好》','',NULL,NULL,'2023-06-25 09:39:11',9843,NULL,'2023-02-28 00:15:26',2),(1579,1,'阅读《head first c》','',NULL,NULL,'2023-06-25 09:40:05',26717,NULL,'2023-03-05 18:24:23',2),(1585,1,'分析open_binance的日志','',NULL,NULL,'2023-06-25 10:57:47',0,NULL,NULL,2),(1586,1,'考虑优化toolbox.round','',NULL,NULL,'2023-06-25 15:06:24',0,NULL,NULL,2),(1588,1,'考虑把相关的df修改成字典','',NULL,NULL,'2023-06-27 09:38:06',0,NULL,NULL,2),(1590,1,'考虑修改多线程日志','',NULL,NULL,'2023-06-30 09:47:51',0,NULL,NULL,2),(1591,1,'考虑优化open_binance','',NULL,NULL,'2023-07-24 09:55:25',0,NULL,NULL,2),(1592,1,'学习《learncpp上的文章》','',NULL,NULL,'2023-07-24 09:57:25',0,NULL,NULL,2),(1593,1,'分析字符串合并相关的问题','',NULL,NULL,'2023-07-24 09:58:02',0,NULL,NULL,2),(1596,1,'实现on_trade','',NULL,NULL,'2023-08-15 09:37:54',0,NULL,NULL,2),(1597,1,'尝试实现backtest进行灌数测试','',NULL,NULL,'2023-08-15 09:46:16',0,NULL,NULL,2),(1599,1,'给lv增加log测试','',NULL,NULL,'2023-08-21 09:54:53',0,NULL,NULL,2),(1601,1,'bit策略改进新框架','',NULL,NULL,'2023-08-29 13:27:49',0,NULL,NULL,2),(1602,1,'namespace使用方法','','2023-08-29 13:29:23','2023-09-30 00:00:00',NULL,0,NULL,NULL,4),(1603,1,'分析self.a 与self.params[a]的效率','',NULL,NULL,'2023-09-03 12:06:09',0,NULL,NULL,2),(1604,1,'python的in操作符的用法','','2023-09-07 10:07:07','2023-09-10 00:00:00',NULL,0,NULL,NULL,5),(1606,1,'理解现货合约等价差变化规律','',NULL,NULL,'2024-01-22 17:29:14',0,NULL,NULL,2),(1607,1,'阅读《搞定》','',NULL,NULL,'2024-01-22 17:29:28',0,NULL,NULL,2),(1608,1,'阅读《搞定3》','',NULL,NULL,'2024-01-22 17:29:32',0,NULL,NULL,2),(1609,1,'学习qmt','',NULL,NULL,'2024-01-22 17:34:21',21460,NULL,'2023-03-21 21:57:44',2),(1610,1,'修改已完成的card,增加修改选项','',NULL,NULL,'2024-01-22 17:34:41',0,NULL,NULL,2);
